// ============================================================================
// Enums
// ============================================================================

export enum SubmissionAnswer {
  Agree = 'agree',
  Prefer = 'prefer',
  Skip = 'skip',
  Confirm = 'confirm',
  Disagree = 'disagree'
}

// ============================================================================
// Models
// ============================================================================

/**
 * A stored submission, as the intake loop reads it.
 */
export interface Submission {
  id: string;
  question_id: string;
  answer: SubmissionAnswer;
  reason?: string;
  name?: string;
  background?: string;
  site_version: string;
  received_at: ISODateTimeString;
}

/**
 * One answer to one question on the questions page.
 */
export interface SubmissionForm {
  /** The key of the question on the questions page, as the site publishes it. */
  question_id: string;
  answer: SubmissionAnswer;
  /** Why, and for `prefer` the rendering preferred. */
  reason?: string;
  /** How the submitter would like to be credited in the changelog. Absent: not credited by name. */
  name?: string;
  /** The submitter's own description of their background, e.g. MEMS engineer, Polish native speaker. */
  background?: string;
  /** The version of the site the question was read on, so an answer is evaluated against the text the submitter saw. */
  site_version: string;
}

/**
 * Acknowledges a stored submission. Carries nothing of what was submitted.
 */
export interface SubmissionReceipt {
  id: string;
  received_at: ISODateTimeString;
}

