import { ValidationErrorsResponse } from './generated-error-validation-errors-response.ts';
import { UnauthorizedErrorResponse } from './generated-error-unauthorized-error-response.ts';
import { ApiException, Util } from './generated-util.ts';
import type { ApiClientOptions } from './generated-util.ts';

export interface CreateSubmissionOptions {
  body: SubmissionForm;
  headers?: Record<string, string>;
  signal?: AbortSignal;
}

export interface GetSubmissionsOptions {
  limit: number;
  offset: number;
  since?: ISODateTimeString;
  headers?: Record<string, string>;
  signal?: AbortSignal;
}

export class ApiClient {
  private baseUrl: string;
  private defaultHeaders: Record<string, string>;
  private timeoutMs: number | undefined;
  private fetchImpl: typeof fetch;

  /**
   * Accepts a bare base URL for backwards compatibility, or an options object carrying
   * the headers every call should send, a request timeout, and a fetch implementation.
   */
  constructor(options: string | ApiClientOptions) {
    const resolved: ApiClientOptions = typeof options === 'string' ? { baseUrl: options } : options;
    this.baseUrl = resolved.baseUrl;
    this.defaultHeaders = resolved.headers ?? {};
    this.timeoutMs = resolved.timeoutMs;
    const fetchImpl = resolved.fetch;
    this.fetchImpl = fetchImpl ?? ((input: RequestInfo | URL, init?: RequestInit) => fetch(input, init));
  }

  private async request(
    url: string,
    init: Omit<RequestInit, 'headers' | 'signal'>,
    contentType: string,
    headers: Record<string, string>,
    signal?: AbortSignal
  ): Promise<Response> {
    const requestInit: RequestInit = {
      ...init,
      headers: { 'Content-Type': contentType, ...this.defaultHeaders, ...headers }
    };
    if (this.timeoutMs === undefined) {
      return this.fetchImpl(url, { ...requestInit, signal: signal ?? null });
    }
    const controller = new AbortController();
    const abort = () => controller.abort();
    if (signal !== undefined) {
      if (signal.aborted) {
        controller.abort();
      } else {
        signal.addEventListener('abort', abort, { once: true });
      }
    }
    const timer = setTimeout(abort, this.timeoutMs);
    try {
      return await this.fetchImpl(url, { ...requestInit, signal: controller.signal });
    } finally {
      clearTimeout(timer);
      if (signal !== undefined) {
        signal.removeEventListener('abort', abort);
      }
    }
  }

  async createSubmission(params: CreateSubmissionOptions): Promise<SubmissionReceipt> {
    const url = `${this.baseUrl}/thesis/submissions`;

    const response = await this.request(
      url,
      {
        method: 'POST',
        body: JSON.stringify(params.body)
      },
      'application/json',
      params.headers || {},
      params.signal
    );

    if (response.status === 201) {
      return await Util.mustParse<SubmissionReceipt>(response, 'SubmissionReceipt');
    }

    if (response.status === 422) {
      throw new ValidationErrorsResponse(response);
    }

    throw new ApiException(response, `Request failed with status ${response.status}`);
  }

  async getSubmissions(params: GetSubmissionsOptions): Promise<Submission[]> {
    const queryParts: string[] = [];
    if (params.since !== undefined && params.since !== null) {
      queryParts.push(`since=${encodeURIComponent(String(params.since))}`);
    }
    queryParts.push(`limit=${encodeURIComponent(String(params.limit))}`);
    queryParts.push(`offset=${encodeURIComponent(String(params.offset))}`);
    const queryString = queryParts.length > 0 ? '?' + queryParts.join('&') : '';
    const url = `${this.baseUrl}/thesis/submissions${queryString}`;

    const response = await this.request(
      url,
      {
        method: 'GET'
      },
      'application/json',
      params.headers || {},
      params.signal
    );

    if (response.status === 200) {
      return await Util.mustParseArray<Submission>(response, 'Submission');
    }

    if (response.status === 401) {
      throw new UnauthorizedErrorResponse(response);
    }

    if (response.status === 422) {
      throw new ValidationErrorsResponse(response);
    }

    throw new ApiException(response, `Request failed with status ${response.status}`);
  }
}
